package de.teamlapen.vampirism.common.core;

import de.teamlapen.faction.api.world.entities.extensions.IEntity;
import de.teamlapen.faction.common.util.AttachmentSynchronization;
import de.teamlapen.faction.common.world.entities.EntitySyncHolder;
import de.teamlapen.sync.PropertySync;
import de.teamlapen.sync.api.IAttachmentSync;
import de.teamlapen.vampirism.REFERENCE;
import de.teamlapen.vampirism.api.VampirismAttachments;
import de.teamlapen.vampirism.common.util.supporter.Supporter;
import de.teamlapen.vampirism.common.world.attachments.LevelDamage;
import de.teamlapen.vampirism.common.world.attachments.LevelFog;
import de.teamlapen.vampirism.common.world.attachments.LevelGarlic;
import de.teamlapen.vampirism.common.world.attachments.NearestVillage;
import de.teamlapen.vampirism.common.world.dimensions.velmorra.VelmorraDimension;
import de.teamlapen.vampirism.common.world.entity.ExtendedCreature;
import de.teamlapen.vampirism.common.world.entity.QuarrelEntity;
import de.teamlapen.vampirism.common.world.entity.dracula.DraculaFightData;
import de.teamlapen.vampirism.common.world.entity.minion.HunterMinionEntity;
import de.teamlapen.vampirism.common.world.entity.minion.VampireMinionEntity;
import de.teamlapen.vampirism.common.world.entity.player.hunter.HunterPlayer;
import de.teamlapen.vampirism.common.world.entity.player.hunter.MarshallPlayer;
import de.teamlapen.vampirism.common.world.entity.player.vampire.DraculaPlayer;
import de.teamlapen.vampirism.common.world.entity.player.vampire.InfectionStatus;
import de.teamlapen.vampirism.common.world.entity.player.vampire.VampireBat;
import de.teamlapen.vampirism.common.world.entity.player.vampire.VampirePlayer;
import net.minecraft.core.GlobalPos;
import net.minecraft.resources.Identifier;
import net.minecraft.world.entity.ambient.Bat;
import net.minecraft.world.entity.player.Player;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.neoforge.attachment.AttachmentType;
import net.neoforged.neoforge.attachment.IAttachmentHolder;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;
import net.neoforged.neoforge.registries.NeoForgeRegistries;

import java.util.function.Function;

public class ModAttachments {
    public static final DeferredRegister<AttachmentType<?>> ATTACHMENT_TYPES = DeferredRegister.create(NeoForgeRegistries.Keys.ATTACHMENT_TYPES, REFERENCE.MODID);

    // Level Attachments
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<LevelFog>> LEVEL_FOG = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.FOG_HANDLER.getPath(), () -> AttachmentType.builder(new LevelFog.Factory()).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<LevelGarlic>> LEVEL_GARLIC = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.GARLIC_HANDLER.getPath(), () -> AttachmentType.builder(new LevelGarlic.Factory()).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<LevelDamage>> LEVEL_DAMAGE = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.DAMAGE_HANDLER.getPath(), () -> AttachmentType.builder(new LevelDamage.Factory()).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<DraculaFightData>> DRACULA_FIGHT_DATA = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.DRACULA_FIGHT_DATA.getPath(), () -> AttachmentType.builder(new DraculaFightData.Factory()).serialize(new DraculaFightData.Serializer()).build());

    // Entity Attachments
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<ExtendedCreature>> EXTENDED_CREATURE = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.EXTENDED_CREATURE.getPath(), () -> syncAttachment(new ExtendedCreature.AttachmentOptions()).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<HunterPlayer>> HUNTER_PLAYER = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.HUNTER_PLAYER.getPath(), () -> syncAttachment(new HunterPlayer.AttachmentOptions()).copyOnDeath().build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<VampirePlayer>> VAMPIRE_PLAYER = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.VAMPIRE_PLAYER.getPath(), () -> syncAttachment(new VampirePlayer.AttachmentOptions()).copyOnDeath().build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<Bat>> VAMPIRE_BAT = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.VAMPIRE_BAT.getPath(), () -> AttachmentType.builder(new VampireBat.Factory()).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<InfectionStatus>> INFECTION_STATUS = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.INFECTION_STATUS.getPath(), () -> AttachmentType.builder(new InfectionStatus.Factory()).serialize(new InfectionStatus.Serializer()).sync(new InfectionStatus.Sync()).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<QuarrelEntity.HurtBypassTracker>> QUARREL_HURT_BYPASS = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.QUARREL_HURT_BYPASS.getPath(), () -> AttachmentType.builder(QuarrelEntity.HurtBypassTracker::new).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<EntitySyncHolder<VampireMinionEntity, VampireMinionEntity.VampireMinionData>>> VAMPIRE_MINION_DATA = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.VAMPIRE_MINION_DATA.getPath(), () -> syncHolder(new EntitySyncHolder.Factory<>(VampireMinionEntity.class)).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<EntitySyncHolder<HunterMinionEntity, HunterMinionEntity.HunterMinionData>>> HUNTER_MINION_DATA = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.HUNTER_MINION_DATA.getPath(), () -> syncHolder(new EntitySyncHolder.Factory<>(HunterMinionEntity.class)).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<GlobalPos>> VELMORRA_PORTAL = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.VELMORRA_PORTAL.getPath(), () -> AttachmentType.builder(new VelmorraDimension.VelmorraPortalPos()).serialize(GlobalPos.MAP_CODEC).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<Identifier>> MARKER = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.MARKER.getPath(), () -> AttachmentType.builder(() -> Identifier.withDefaultNamespace("none")).serialize(Identifier.CODEC.fieldOf("key")).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<DraculaPlayer>> DRACULA_PLAYER = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.DRACULA_PLAYER.getPath(), () -> playerAttachment(DraculaPlayer::new).copyOnDeath().build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<MarshallPlayer>> MARSHALL_PLAYER = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.MARSHALL_PLAYER.getPath(), () -> playerAttachment(MarshallPlayer::new).copyOnDeath().build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<Supporter>> SUPPORTER = ATTACHMENT_TYPES.register("supporter", () -> AttachmentType.<Supporter>builder(Supporter::defaultSupplier).sync(Supporter.STREAM_CODEC).serialize(Supporter.CODEC).build());

    //Blocks Attachments
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<NearestVillage>> NEAREST_VILLAGE = ATTACHMENT_TYPES.register(VampirismAttachments.Keys.NEAREST_VILLAGE.getPath(), () -> AttachmentType.builder(new NearestVillage.Factory()).build());

    static void register(IEventBus bus) {
        ATTACHMENT_TYPES.register(bus);
    }

    private static <T extends IAttachmentSync & IEntity> AttachmentType.Builder<T> playerAttachment(Function<Player, T> options) {
        return syncAttachment(new AttachmentSynchronization.PlayerOptions<>() {
            @Override
            protected T create(Player player) {
                return options.apply(player);
            }
        });
    }

    private static <T extends IAttachmentSync & IEntity, Z extends IAttachmentHolder> AttachmentType.Builder<T> syncAttachment(AttachmentSynchronization<T, Z> options) {
        return AttachmentType.builder(options).serialize(options).sync(options);
    }

    private static <TEntity extends EntitySyncHolder.ISyncHolder<TData>, TData extends PropertySync> AttachmentType.Builder<EntitySyncHolder<TEntity, TData>> syncHolder(EntitySyncHolder.Factory<TEntity, TData> options) {
        return AttachmentType.builder(options).sync(options);
    }

}

package de.teamlapen.vampirism.common.server;

import de.teamlapen.vampirism.common.util.UtilLib;
import de.teamlapen.vampirism.misc.extension.ISpawnState;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.*;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.NaturalSpawner;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.common.util.ValueIOSerializable;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.Collections;
import java.util.Random;
import java.util.function.Consumer;

/**
 * Simple mob spawning logic. More configurable than {@link net.minecraft.world.level.BaseSpawner} but less functional.
 */
public class SimpleSpawnerLogic<T extends Entity> implements ValueIOSerializable {

    private final static Logger LOGGER = LogManager.getLogger();
    private static final int MOB_COUNT_DIV = (int) Math.pow(17.0D, 2.0D);

    @NotNull
    private final EntityType<T> entityType;
    @Nullable
    private Consumer<T> onSpawned;
    private int minSpawnDelay = 200;
    private int maxSpawnDelay = 800;
    private int activateRange = 16;
    private int dailyLimit = Integer.MAX_VALUE;
    private int spawnCount = 1;
    private int maxNearbyEntities = 4;
    private int spawnRange = 4;
    private int spawnDelay = 20;
    private int spawnedToday = 0;
    private long spawnedLast = 0L;
    private boolean flag = true;
    private MobCategory limitType;
    private final Random rng = new Random();

    public SimpleSpawnerLogic(@NotNull EntityType<T> entityTypeIn) {
        this.entityType = entityTypeIn;
    }

    @NotNull
    public EntityType<T> getEntityType() {
        return entityType;
    }

    public int getSpawnedToday() {
        return spawnedToday;
    }

    public boolean isActivated(@Nullable Level level, @Nullable BlockPos pos) {
        if (level == null) return false;
        if (pos == null) return false;
        return level.hasNearbyAlivePlayer(pos.getX() + 0.5D, pos.getY() + 0.5D, pos.getZ() + 0.5D, this.activateRange);
    }

    public @NotNull SimpleSpawnerLogic<T> setActivateRange(int activateRange) {
        this.activateRange = activateRange;
        return this;
    }

    public @NotNull SimpleSpawnerLogic<T> setDailyLimit(int dailyLimit) {
        this.dailyLimit = dailyLimit;
        return this;
    }

    public boolean setDelayToMin(int id, @NotNull Level level) {
        if (id == 1 && (level.isClientSide())) {
            this.spawnDelay = this.minSpawnDelay;
            return true;
        } else {
            return false;
        }
    }

    /**
     * Checks if any more creatures of the given type are allowed in the world before spawning
     */
    public @NotNull SimpleSpawnerLogic<T> setLimitTotalEntities(MobCategory creatureType) {
        limitType = creatureType;
        return this;
    }

    public @NotNull SimpleSpawnerLogic<T> setMaxNearbyEntities(int maxNearbyEntities) {
        this.maxNearbyEntities = maxNearbyEntities;
        return this;
    }

    public @NotNull SimpleSpawnerLogic<T> setMaxSpawnDelay(int maxSpawnDelay) {
        this.maxSpawnDelay = maxSpawnDelay;
        return this;
    }

    public @NotNull SimpleSpawnerLogic<T> setMinSpawnDelay(int minSpawnDelay) {
        this.minSpawnDelay = minSpawnDelay;
        return this;
    }

    public @NotNull SimpleSpawnerLogic<T> setOnSpawned(Consumer<T> onSpawned) {
        this.onSpawned = onSpawned;
        return this;
    }

    public @NotNull SimpleSpawnerLogic<T> setSpawn(boolean spawn) {
        this.flag = spawn;
        return this;
    }

    public @NotNull SimpleSpawnerLogic<T> setSpawnCount(int spawnCount) {
        this.spawnCount = spawnCount;
        return this;
    }

    public @NotNull SimpleSpawnerLogic<T> setSpawnRange(int spawnRange) {
        this.spawnRange = spawnRange;
        return this;
    }

    public void serverTick(Level level, @NotNull BlockPos pos) {
        if (isActivated(level, pos)) {
            if (level instanceof ServerLevel) {
                if (this.spawnDelay == -1) {
                    this.resetTimer();
                }

                if (this.spawnDelay > 0) {
                    --this.spawnDelay;
                    return;
                }


                if ((level.getGameTime()) > this.spawnedLast + 24000) {
                    this.spawnedToday = 0;
                    this.flag = true;
                } else if (this.spawnedToday >= dailyLimit) {
                    this.flag = false;
                }
                if (!this.flag) {
                    return;
                }

                boolean flag1 = false;

                for (int i = 0; i < this.spawnCount; ++i) {
                    T entity = this.getEntityType().create(level, EntitySpawnReason.SPAWNER);

                    if (entity == null) {
                        break;
                    }

                    int j = level.getEntitiesOfClass(entity.getClass(), getSpawningBox(pos).inflate(5)).size();

                    if (j >= this.maxNearbyEntities) {
                        this.resetTimer();
                        break;
                    }

                    if (limitType != null) {
                        @Nullable
                        NaturalSpawner.SpawnState densityManager = ((ServerLevel) level).getChunkSource().getLastSpawnState();
                        try {
                            if (densityManager != null && !((ISpawnState) densityManager).vampirism$canSpawnForCategoryLocalI(limitType, new ChunkPos(pos.getX() / 16, pos.getZ() / 16))) {
                                this.resetTimer();
                                break;
                            }
                        } catch (NoSuchMethodError e) {
                            //Workaround for https://github.com/TeamLapen/Vampirism/issues/983
                            //Maybe remove when https://github.com/magmafoundation/Magma-1.16.x/issues/154 is solved
                        }

                    }

                    if (UtilLib.spawnEntityInWorld((ServerLevel) level, getSpawningBox(pos), entity, 1, Collections.emptyList(), EntitySpawnReason.SPAWNER)) {
                        onSpawned(entity);
                        flag1 = true;
                    }
                }
                if (flag1) {
                    this.resetTimer();
                    this.spawnedToday++;
                    this.spawnedLast = level.getGameTime();
                }
            }
        }
    }

    @Override
    public void serialize(ValueOutput output) {
        output.putInt("delay", spawnDelay);
        output.putInt("spawned_today", spawnedToday);
        output.putLong("spawned_last", spawnedLast);
        output.putBoolean("spawner_flag", flag);
    }

    @Override
    public void deserialize(ValueInput input) {
        this.spawnDelay = input.getIntOr("delay", 0);
        this.spawnedToday = input.getIntOr("spawned_today", 0);
        this.spawnedLast = input.getLongOr("spawned_last", 0);
        this.flag = input.getBooleanOr("spawner_flag", false);
    }

    protected @NotNull AABB getSpawningBox(@Nullable BlockPos pos) {
        if (pos == null) return AABB.ofSize(Vec3.ZERO, 0, 0, 0);
        return (new AABB(pos.getX(), pos.getY(), pos.getZ(), pos.getX() + 1, pos.getY() + 1, pos.getZ() + 1)).inflate(this.spawnRange, this.spawnRange, this.spawnRange);

    }

    protected void onSpawned(T e) {
        if (e instanceof Mob mob) {
            mob.spawnAnim();
        }
        if (this.onSpawned != null) {
            this.onSpawned.accept(e);
        }
    }

    private void resetTimer() {
        if (this.maxSpawnDelay <= this.minSpawnDelay) {
            this.spawnDelay = this.minSpawnDelay;
        } else {
            int i = this.maxSpawnDelay - this.minSpawnDelay;
            this.spawnDelay = this.minSpawnDelay + (rng.nextInt(i));
        }
    }
}

package de.teamlapen.vampirism.common.world.blockentity;

import de.teamlapen.faction.api.factions.level.FactionUpdate;
import de.teamlapen.faction.common.factions.FactionPlayerHandler;
import de.teamlapen.faction.common.util.SpawnUtil;
import de.teamlapen.faction.common.world.blockentity.NetworkedBlockEntity;
import de.teamlapen.vampirism.common.core.*;
import de.teamlapen.vampirism.common.network.packets.client.ClientboundBossEventSoundPacket;
import de.teamlapen.vampirism.common.network.packets.client.ClientboundPlayEventPacket;
import de.teamlapen.vampirism.common.particles.MotherParticleOptions;
import de.teamlapen.vampirism.common.world.blocks.mother.IRemainsBlock;
import de.teamlapen.vampirism.common.world.blocks.mother.MotherTreeStructure;
import de.teamlapen.vampirism.common.world.entity.GhostEntity;
import net.minecraft.core.BlockPos;
import net.minecraft.core.UUIDUtil;
import net.minecraft.core.particles.DustParticleOptions;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerBossEvent;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundSource;
import net.minecraft.util.Mth;
import net.minecraft.util.RandomSource;
import net.minecraft.world.BossEvent;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.EntitySpawnReason;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;
import org.apache.commons.lang3.tuple.Triple;
import org.jetbrains.annotations.Nullable;

import java.util.*;
import java.util.stream.Collectors;
import java.util.stream.Stream;


public class MotherBlockEntity extends NetworkedBlockEntity {

    public static void serverTick(Level level, BlockPos blockPos, BlockState blockState, MotherBlockEntity e) {

        //Handle fight ---------------------------------
        if (e.isFrozen && e.freezeTimer-- <= 0) {
            e.unFreezeFight(level, blockPos, blockState);
        }
        if (!e.isFrozen && e.level != null && e.isIntact()) {
            if (e.level.getRandom().nextInt(50) == 0) {
                e.updateFightStatus();
                if (!e.activePlayers.isEmpty()) {
                    List<Triple<BlockPos, BlockState, IRemainsBlock>> vuls = e.getTreeStructure(false).getVerifiedVulnerabilities(level).filter(t -> t.getRight().isVulnerable(t.getMiddle())).toList();
                    if (!vuls.isEmpty()) {
                        for (ServerPlayer player : e.activePlayers) {
                            if (player.getAbilities().invulnerable) {
                                continue;
                            }
                            BlockPos p = vuls.get(e.level.getRandom().nextInt(vuls.size())).getLeft();
                            player.addEffect(new MobEffectInstance(MobEffects.HUNGER, 5 * 20, 2));
                            ModParticles.spawnParticlesServer(player.level(), new MotherParticleOptions(100, false, p.getX() + 0.5, p.getY() + 0.5, p.getZ() + 0.5, 0.5f), player.getX(), player.getY() + player.getEyeHeight() / 2, player.getZ(), 5, 0.1f, 0.1f, 0.1f, 0);
                        }
                    }
                }
            }
            if (e.level.getRandom().nextFloat() < Math.clamp(e.activePlayers.size() * 0.002f, 0.02f, 0.1f)) {
                var blocks = e.getTreeStructure(false).getCachedBlocks();
                if (e.level.getEntitiesOfClass(GhostEntity.class, e.getArea().inflate(10)).size() < Math.min(e.activePlayers.size() * 1.6, 10)) {
                    blocks.stream().skip(e.level.getRandom().nextInt(blocks.size())).findFirst().ifPresent(pos -> e.spawnGhost(level, pos));
                }
            }
        }
        //Handle destruction --------------------------------
        if (e.level != null && e.destructionTimer > 0) {
            if (e.destructionTimer++ % 3 == 0) {
                MotherTreeStructure structure = e.getTreeStructure(false);
                Optional<Set<BlockPos>> hierarchy = structure.popHierarchy();
                if (hierarchy.isPresent()) {
                    for (BlockPos p : hierarchy.get()) {
                        if (level.getBlockState(p).getBlock() instanceof IRemainsBlock) {
                            level.setBlock(p, Blocks.AIR.defaultBlockState(), 3);
                            ModParticles.spawnParticlesServer(level, new DustParticleOptions(1, -1), p.getX() + 0.5, p.getY() + 0.5, p.getZ() + 0.5f, 20, 0.3, 0.3, 0.3, 0.01);
                            e.level.playSound(null, p, ModSounds.REMAINS_DEATH.get(), SoundSource.BLOCKS, 0.2f, 1f);
                        }
                    }
                } else {
                    //Destruction complete
                    e.destructionTimer = -1;
                    if (e.level != null) {
                        e.level.playSound(null, blockPos, ModSounds.MOTHER_DEATH.get(), SoundSource.BLOCKS, 2f, 0.8f);
                    }
                    e.concludeFight();
                }
            }
        }
        if (level.getGameTime() % 64 == 0) {
            AABB area = e.getArea();
            Stream.concat(e.activePlayers.stream(), e.bossEvent.getPlayers().stream()).distinct().filter(player -> area.distanceToSqr(player.position()) > 1600).toList().forEach(player -> {
                e.bossEvent.removePlayer(player);
                e.activePlayers.remove(player);
            });
            AABB inflate = area.inflate(5, 5, 5);
            AABB inflate2 = inflate.inflate(10, 10, 10);
            if (!e.activePlayers.isEmpty()) {
                inflate = inflate.inflate(10, 10, 10);
                inflate2 = inflate2.inflate(20, 10, 20);
            }
            if (e.isIntact()) {
                level.getEntitiesOfClass(ServerPlayer.class, inflate).forEach(e::addPlayer);
            }
            level.getEntitiesOfClass(ServerPlayer.class, inflate2).forEach(e::addPlayerToBossEvent);
        }
    }

    private static final RandomSource RANDOM = RandomSource.create();
    private final ServerBossEvent bossEvent = new ServerBossEvent(Mth.createInsecureUUID(RANDOM),Component.translatable("block.vampirism.mother"), BossEvent.BossBarColor.RED, BossEvent.BossBarOverlay.NOTCHED_10);
    private final Set<ServerPlayer> activePlayers = new HashSet<>();
    private final Set<UUID> involvedPlayers = new HashSet<>();
    /**
     * Cache structure. Should be mostly valid because blocks cannot be destroyed by survival player. Is (unreliably) invalidated when a block is destroyed nonetheless.
     */
    @Nullable
    private MotherTreeStructure cachedStructure;
    private boolean isFrozen = false;
    private int freezeTimer = 0;
    @Nullable
    private AABB area;

    public MotherBlockEntity(BlockPos pos, BlockState state) {
        super(ModBlockEntities.MOTHER.get(), pos, state);
        this.bossEvent.setProgress(1);
        this.bossEvent.setPlayBossMusic(true);
    }

    /**
     * Describes the destruction process
     * <p>== 0: Intact</p>
     * <p>> 0: Increasing, destruction in progress</p>
     * <p>== -1: Structure, destroyed, mother is vulnerable</p>
     */
    private int destructionTimer = 0;

    public boolean isCanBeBroken() {
        return this.destructionTimer == -1;
    }

    public boolean isIntact() {
        return this.destructionTimer == 0;
    }

    @Override
    public void loadAdditional(ValueInput input) {
        super.loadAdditional(input);
        this.destructionTimer = input.getIntOr("destruction_timer", 0);
        this.isFrozen = input.getBooleanOr("is_frozen", false);
        this.freezeTimer = input.getIntOr("freeze_timer", 0);
        if (this.isFrozen) {
            this.bossEvent.setColor(BossEvent.BossBarColor.WHITE);
        }
        this.involvedPlayers.clear();
        input.listOrEmpty("involved_players", UUIDUtil.CODEC).forEach(this.involvedPlayers::add);
    }

    @Override
    protected void saveAdditional(ValueOutput output) {
        super.saveAdditional(output);
        output.putInt("destruction_timer", this.destructionTimer);
        output.putBoolean("is_frozen", this.isFrozen);
        output.putInt("freeze_timer", this.freezeTimer);
        var involvedPlayers = output.list("involved_players", UUIDUtil.CODEC);
        this.involvedPlayers.forEach(involvedPlayers::add);
    }

    /**
     * Call this when a block that belongs to this structure is removed
     */
    public void onStructureBlockRemoved() {
        this.cachedStructure = null;
    }

    @Override
    public void setRemoved() {
        super.setRemoved();
        this.bossEvent.removeAllPlayers();
        this.activePlayers.clear();
    }

    private void addPlayer(Player player) {
        if (player instanceof ServerPlayer serverPlayer && !this.activePlayers.contains(serverPlayer)) {
            updateFightStatus();
            addPlayerToBossEvent(serverPlayer);
            this.activePlayers.add(serverPlayer);
        }
    }

    private void addPlayerToBossEvent(ServerPlayer player) {
        this.bossEvent.addPlayer(player);
        player.connection.send(new ClientboundBossEventSoundPacket(this.bossEvent.getId(), ModSounds.MOTHER_AMBIENT.getKey()));
    }

    public void onVulnerabilityHit(LivingEntity entity, boolean destroyed) {
        if (entity instanceof ServerPlayer player) {
            informAboutAttacker(player);
        }
        updateFightStatus();
        if (destroyed && isIntact()) {
            freezeFight();
        }
    }

    public void updateFightStatus() {
        List<Triple<BlockPos, BlockState, IRemainsBlock>> vuls = getTreeStructure(false).getVerifiedVulnerabilities(level).toList();
        List<Triple<BlockPos, BlockState, IRemainsBlock>> remaining = vuls.stream().filter(vul -> vul.getRight().isVulnerable(vul.getMiddle())).toList();
        if (!remaining.isEmpty()) {
            var remainingHealth = remaining.stream().mapToInt(s -> {
                if (level.isLoaded(s.getLeft())) { //Check whether still loaded
                    var entity = level.getBlockEntity(s.getLeft());
                    if (entity instanceof VulnerableRemainsBlockEntity vulnerable) {
                        return vulnerable.getHealth();
                    }
                }
                return VulnerableRemainsBlockEntity.MAX_HEALTH;
            }).sum();
            this.bossEvent.setProgress(remainingHealth / ((float) vuls.size() * VulnerableRemainsBlockEntity.MAX_HEALTH));
        } else {
            this.bossEvent.setProgress(0);
            this.endFight();
        }
    }

    private void endFight() {
        this.activePlayers.forEach(p -> p.connection.send(new ClientboundPlayEventPacket(ClientboundPlayEventPacket.Event.STOP_MUSIC)));
        this.bossEvent.removeAllPlayers();
        this.bossEvent.setVisible(false);
        this.activePlayers.clear();
        this.initiateDestruction();
    }

    private void freezeFight() {
        spawnGhosts();
        this.isFrozen = true;
        this.freezeTimer = 20 * 20;
        getTreeStructure(false).getVerifiedVulnerabilities(this.level).forEach(vul -> vul.getRight().freeze(level, vul.getLeft(), vul.getMiddle()));
        this.bossEvent.setColor(BossEvent.BossBarColor.WHITE);
    }

    private MotherTreeStructure getTreeStructure(boolean forceRefresh) {
        if (forceRefresh || this.cachedStructure == null) {
            this.cachedStructure = MotherTreeStructure.getTreeView(this.level, this.worldPosition);
        }
        return cachedStructure;
    }

    private void initiateDestruction() {
        this.getTreeStructure(true);
        this.destructionTimer = 1;
    }

    private void unFreezeFight(Level level, BlockPos blockPos, BlockState blockState) {
        this.isFrozen = false;
        getTreeStructure(false).getVerifiedVulnerabilities(this.level).forEach(vul -> vul.getRight().unFreeze(level, vul.getLeft(), vul.getMiddle()));
        this.bossEvent.setColor(BossEvent.BossBarColor.RED);
    }

    public void informAboutAttacker(ServerPlayer serverPlayer) {
        addPlayer(serverPlayer);
        this.involvedPlayers.add(serverPlayer.getUUID());
    }

    public Collection<ServerPlayer> involvedPlayers() {
        return this.activePlayers;
    }

    private void spawnGhost(Level level, BlockPos pos) {
        SpawnUtil.spawn(ModEntities.GHOST, level, EntitySpawnReason.STRUCTURE, ghost -> {
            ghost.setPos(Vec3.atCenterOf(pos));
            ghost.setHome(getArea().inflate(15));
        });
    }

    private AABB getArea() {
        if (this.area == null) {
            this.area = new AABB(this.worldPosition).inflate(9, 0, 9).expandTowards(0, -10, 0).expandTowards(0, 4, 0);
        }
        return this.area;
    }

    private void spawnGhosts() {
        Set<BlockPos> vuls = this.getTreeStructure(false).getCachedBlocks();
        int size = this.level.getEntitiesOfClass(GhostEntity.class, this.getArea()).size();
        for (int i = size; i < Math.clamp(this.activePlayers.size() * 1.6, 3, 10); i++) {
            vuls.stream().skip(level.getRandom().nextInt(vuls.size())).findFirst().ifPresent(pos -> this.spawnGhost(level, pos));
        }
    }

    public void concludeFight() {
        //noinspection DataFlowIssue
        Set<LivingEntity> involvedEntities = this.involvedPlayers.stream().map(((ServerLevel) this.level)::getEntity).filter(LivingEntity.class::isInstance).filter(s -> !s.isSpectator()).map(LivingEntity.class::cast).collect(Collectors.toSet());
        for (LivingEntity livingentity : involvedEntities) {
            if (livingentity instanceof ServerPlayer serverplayer) {
                ModAdvancements.TRIGGER_MOTHER_WIN.get().trigger(serverplayer);
                serverplayer.awardStat(ModStats.MOTHER_DEFEATED.get(), 1);
                FactionPlayerHandler handler = FactionPlayerHandler.get(serverplayer);
                if (handler.getCurrentLevel() < handler.getFaction().value().getHighestReachableLevel()) {
                    handler.setFaction(FactionUpdate.builder().level(handler.getCurrentLevel() + 1));
                }
            }
        }
    }
}

package de.teamlapen.vampirism.common.world.blockentity;

